#!/usr/bin/env node
// Regenerates packages/sdk/src/generated/openapi-tax-code-contract.ts from
// the public contract published in the sibling clearvo-marketing repo
// (public/openapi.json). This is the ONE place the tax-code-mapping hard
// cut's public contract gets turned into real TypeScript the SDK actually
// imports (see packages/sdk/src/types.ts's TaxTreatment re-export) — never
// hand-edit the generated file.
//
// Usage:
//   node scripts/generate-from-openapi.mjs           write the generated file
//   node scripts/generate-from-openapi.mjs --check    regenerate in memory and
//                                                      diff against the committed
//                                                      file; exit 1 on any
//                                                      mismatch (this is what CI
//                                                      runs — see
//                                                      `npm run test:codegen-diff`)
//
// Sibling-checkout gated (same pattern as this org's other cross-repo drift
// guards, e.g. Taxually-Einvoicing's fixurl-frontend-route-drift.test.ts):
// resolves the openapi.json path from CLEARVO_MARKETING_OPENAPI_PATH, or
// tries a short list of conventional sibling-checkout locations. When none
// exist, `--check` exits 0 with a skip notice rather than failing — a
// developer without the sibling repo checked out must not be blocked, but
// CI (which explicitly checks out the sibling — see .github/workflows/ci.yml)
// gets a real, enforcing diff.

import { readFileSync, writeFileSync, existsSync, mkdirSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = resolve(__dirname, '..');
const OUT_PATH = join(REPO_ROOT, 'packages/sdk/src/generated/openapi-tax-code-contract.ts');

function findOpenApiPath() {
  const candidates = [
    process.env.CLEARVO_MARKETING_OPENAPI_PATH,
    join(REPO_ROOT, '../clearvo-marketing/public/openapi.json'),
    join(REPO_ROOT, '../clearvo-marketing-tax-code-mapping/public/openapi.json'),
  ].filter(Boolean);
  return candidates.find((p) => existsSync(p)) ?? null;
}

function loadOpenApi(path) {
  return JSON.parse(readFileSync(path, 'utf8'));
}

function tsUnion(values) {
  return values.map((v) => `'${v}'`).join(' | ');
}

function tsStringArray(values, indent = '  ') {
  return values.map((v) => `${indent}'${v}',`).join('\n');
}

/** Fields that must never carry a `taxCode` property post hard-cut. Throws if the contract regresses. */
function assertNoTaxCode(schemas, schemaName) {
  const schema = schemas[schemaName];
  if (!schema) throw new Error(`openapi.json is missing expected schema '${schemaName}' — cannot generate contract types.`);
  if (schema.properties && Object.prototype.hasOwnProperty.call(schema.properties, 'taxCode')) {
    throw new Error(
      `openapi.json's ${schemaName} schema has a 'taxCode' property again — the tax-code-mapping hard cut ` +
      `removed this field permanently. Fix the schema, don't regenerate against it.`
    );
  }
}

function generate(openapi) {
  const schemas = openapi.components?.schemas ?? {};

  for (const name of ['LineItem', 'Shipping', 'AllowanceCharge']) {
    assertNoTaxCode(schemas, name);
  }

  const taxTreatment = schemas.TaxTreatment;
  if (!taxTreatment || !Array.isArray(taxTreatment.enum)) {
    throw new Error(`openapi.json is missing components.schemas.TaxTreatment.enum — cannot generate TaxTreatment.`);
  }

  const clearanceStatus = schemas.ClearanceStatus;
  if (!clearanceStatus || !Array.isArray(clearanceStatus.enum)) {
    throw new Error(`openapi.json is missing components.schemas.ClearanceStatus.enum — cannot generate ClearanceStatus.`);
  }
  if (!clearanceStatus.enum.includes('HELD_UNMAPPED_TAX_CODE')) {
    throw new Error(`openapi.json's ClearanceStatus.enum no longer contains 'HELD_UNMAPPED_TAX_CODE' — the tax-code-mapping hard cut depends on it.`);
  }

  const taxCodesPath = openapi.paths?.['/tax/codes'];
  if (!taxCodesPath || !taxCodesPath.get) {
    throw new Error(`openapi.json is missing GET /tax/codes — cannot confirm the canonical tax-code catalogue endpoint exists.`);
  }

  return `// AUTO-GENERATED by scripts/generate-from-openapi.mjs — DO NOT EDIT BY HAND.
//
// Source: clearvo-marketing's public/openapi.json (components.schemas.TaxTreatment,
// components.schemas.ClearanceStatus, GET /tax/codes). Regenerate with:
//   node scripts/generate-from-openapi.mjs
// (run from the clearvo-js repo root, with clearvo-marketing checked out as a
// sibling directory, or CLEARVO_MARKETING_OPENAPI_PATH pointed at its
// public/openapi.json). CI's \`npm run test:codegen-diff\` fails the build if
// this file drifts from a fresh regeneration — see .github/workflows/ci.yml.

/**
 * An explicit tax-treatment hint for a line, \`shipping\`, or an
 * allowance/charge on POST /v1/send — used only when \`clientTaxCode\` is
 * omitted, to disambiguate a genuinely 0% line. Mirrors
 * components.schemas.TaxTreatment.enum in openapi.json exactly.
 */
export type TaxTreatment = ${tsUnion(taxTreatment.enum)};

export const TAX_TREATMENTS = [
${tsStringArray(taxTreatment.enum)}
] as const satisfies readonly TaxTreatment[];

/**
 * POST /v1/send's clearanceStatus values. Mirrors
 * components.schemas.ClearanceStatus.enum in openapi.json exactly —
 * including HELD_UNMAPPED_TAX_CODE, the tax-code-mapping hard cut's own
 * status for an unrecognised clientTaxCode/taxTreatment.
 */
export type ClearanceStatus = ${tsUnion(clearanceStatus.enum)};

export const CLEARANCE_STATUSES = [
${tsStringArray(clearanceStatus.enum)}
] as const satisfies readonly ClearanceStatus[];
`;
}

function main() {
  const check = process.argv.includes('--check');
  const openApiPath = findOpenApiPath();

  if (!openApiPath) {
    const msg = 'clearvo-marketing/public/openapi.json not found (checked CLEARVO_MARKETING_OPENAPI_PATH and conventional sibling-checkout paths).';
    if (check) {
      console.log(`SKIP: ${msg} Not failing — this check only enforces when the sibling repo is checked out (CI always checks it out; see .github/workflows/ci.yml).`);
      process.exit(0);
    }
    console.error(`ERROR: ${msg}`);
    process.exit(1);
  }

  const openapi = loadOpenApi(openApiPath);
  const generated = generate(openapi);

  if (check) {
    const existing = existsSync(OUT_PATH) ? readFileSync(OUT_PATH, 'utf8') : null;
    if (existing !== generated) {
      console.error(`FAIL: ${OUT_PATH} is out of date with ${openApiPath}.`);
      console.error(`Run: node scripts/generate-from-openapi.mjs`);
      process.exit(1);
    }
    console.log('OK: generated contract file matches openapi.json.');
    return;
  }

  mkdirSync(dirname(OUT_PATH), { recursive: true });
  writeFileSync(OUT_PATH, generated);
  console.log(`Wrote ${OUT_PATH} from ${openApiPath}`);
}

try {
  main();
} catch (err) {
  console.error(`ERROR: ${err instanceof Error ? err.message : String(err)}`);
  process.exit(1);
}
